// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonAdmin, address newOwner) public {
        vm.assume(nonAdmin != address(0x7FA9385bE102ac3EAc297483Dd6233D62b3e1496));
        vm.assume(nonAdmin != address(this));
        vm.assume(nonAdmin != address(c));
        vm.assume(nonAdmin != address(0));

        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Non-admin should not be able to call setOwner");
    }
}
